//! Why a docs build fails, and its exit code (api-docs-generation spec).

use rustman_core::ConfigError;

/// Usage or configuration error (`rustman` exit code 2).
const CONFIG: u8 = 2;

/// A secret reached the output (exit code 1, like a failed check).
const LEAK: u8 = 1;

#[derive(Debug, thiserror::Error)]
pub enum DocsError {
    /// The workspace, an environment or a setting is invalid.
    #[error(transparent)]
    Config(#[from] ConfigError),
    /// `--out` holds files `rustman docs` did not write.
    #[error("{0} is not empty and was not generated by rustman docs; use --force")]
    NotEmpty(String),
    /// `[docs].publish_variables` names a secret.
    #[error("{0} is a secret and cannot be published")]
    SecretPublished(String),
    /// A setting or flag that cannot be used.
    #[error("docs: {0}")]
    Usage(String),
    /// A layout template that cannot be parsed or rendered.
    #[error("docs: template {name}: {message}")]
    Template { name: String, message: String },
    /// The post-build leak scan found a secret value in these files (shown
    /// under `--out`); they were removed.
    #[error("{}", leak_message(.0))]
    Leak(Vec<String>),
    /// The preview server cannot listen on its address.
    #[error("docs: cannot bind {addr}: {reason}")]
    Bind { addr: String, reason: String },
    #[error("docs: {path}: {source}")]
    Io {
        path: String,
        source: std::io::Error,
    },
}

fn leak_message(files: &[String]) -> String {
    files
        .iter()
        .map(|f| format!("secret value found in {f}"))
        .collect::<Vec<_>>()
        .join("\n")
}

impl DocsError {
    /// The `rustman` exit code for this error.
    pub fn exit_code(&self) -> u8 {
        match self {
            Self::Leak(_) => LEAK,
            _ => CONFIG,
        }
    }

    pub(crate) fn io(path: &std::path::Path, source: std::io::Error) -> Self {
        Self::Io {
            path: path.display().to_string(),
            source,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn messages_and_codes_follow_the_spec() {
        let not_empty = DocsError::NotEmpty("site/".into());
        assert_eq!(
            not_empty.to_string(),
            "site/ is not empty and was not generated by rustman docs; use --force"
        );
        assert_eq!(not_empty.exit_code(), 2);
        let secret = DocsError::SecretPublished("token".into());
        assert_eq!(
            secret.to_string(),
            "token is a secret and cannot be published"
        );
        assert_eq!(secret.exit_code(), 2);
        let leak = DocsError::Leak(vec!["site/index.html".into(), "site/a.html".into()]);
        assert_eq!(
            leak.to_string(),
            "secret value found in site/index.html\nsecret value found in site/a.html"
        );
        assert_eq!(leak.exit_code(), 1);
        let bind = DocsError::Bind {
            addr: "127.0.0.1:4000".into(),
            reason: "address in use".into(),
        };
        assert_eq!(
            bind.to_string(),
            "docs: cannot bind 127.0.0.1:4000: address in use"
        );
        assert_eq!(bind.exit_code(), 2);
    }
}
